.modal-content {
  width: 800px;
  max-width: calc(100vw - 4rem);
}

.fields {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.5em 1em;
}

.actions {
  flex-wrap: wrap;
  justify-content: flex-end;
  row-gap: 0.5em;
}

.info-message {
  margin-top: 1em;
}

.widden {
  margin-bottom: 12em;
}

.flexrow-item {
  margin-right: 0;
}

.disclaimer {
  font-size: 0.8em;
  font-style: italic;
}
</style>
